<?php
include_once './_common.php';nl_require_permission('content_write_policy');$t=nl_table('glossary');
if($_SERVER['REQUEST_METHOD']==='POST'){nl_verify_csrf();$action=nl_post_str('action');if($action==='save'){$id=(int)nl_post_str('id','0');$term=substr(nl_post_str('term'),0,150);$cat=substr(nl_post_str('category'),0,100);$summary=nl_post_str('summary');$detail=nl_post_str('detail');$st=substr(nl_post_str('source_title'),0,255);$urlRaw=nl_post_str('source_url');$url=$urlRaw?nl_safe_external_url($urlRaw):'';if(!$term||!$summary)alert('용어와 요약은 필수입니다.');if($urlRaw&&!$url)alert('출처 URL은 http 또는 https 주소만 사용할 수 있습니다.');$vals=array_map('nl_sql_escape',array($term,$cat,$summary,$detail,$st,$url));$now=nl_now();if($id)sql_query("UPDATE {$t} SET term='{$vals[0]}',category='{$vals[1]}',summary='{$vals[2]}',detail='{$vals[3]}',source_title='{$vals[4]}',source_url='{$vals[5]}',updated_at='{$now}' WHERE id={$id}",false);else sql_query("INSERT INTO {$t} (term,category,summary,detail,source_title,source_url,is_active,created_at,updated_at) VALUES ('{$vals[0]}','{$vals[1]}','{$vals[2]}','{$vals[3]}','{$vals[4]}','{$vals[5]}',1,'{$now}','{$now}')",false);nl_audit('glossary_save','glossary',$id?:$term);goto_url(nl_url('glossary-manage.php'));}if($action==='toggle'){$id=(int)nl_post_str('id','0');$active=(int)nl_post_str('active','0')?1:0;sql_query("UPDATE {$t} SET is_active={$active},updated_at='".nl_now()."' WHERE id={$id}",false);nl_audit('glossary_toggle','glossary',$id,array('active'=>$active));goto_url(nl_url('glossary-manage.php'));}}
$editId=(int)nl_get_str('edit','0');$edit=$editId?sql_fetch("SELECT * FROM {$t} WHERE id={$editId}",false):array();$res=sql_query("SELECT * FROM {$t} ORDER BY term",false);$rows=array();if($res)while($r=sql_fetch_array($res))$rows[]=$r;nl_enqueue_assets();$g5['title']='정책단어 관리';include_once G5_PATH.'/head.php';
?>
<div class="nl-page"><div class="nl-page-head"><p class="nl-kicker">콘텐츠 운영</p><h1>정책단어 관리</h1><p>출처 URL은 서버에서 http/https만 허용해 잘못된 스크립트 URL 저장을 막습니다.</p></div><div class="nl-grid nl-grid--2"><form class="nl-panel nl-form" method="post"><?php echo nl_csrf_field(); ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?php echo (int)($edit['id']??0); ?>"><h2><?php echo $edit?'용어 수정':'새 용어'; ?></h2><div class="nl-field"><label>용어</label><input name="term" value="<?php echo nl_h($edit['term']??''); ?>" required maxlength="150"></div><div class="nl-field"><label>분야</label><input name="category" value="<?php echo nl_h($edit['category']??''); ?>" maxlength="100"></div><div class="nl-field"><label>요약</label><textarea name="summary" required><?php echo nl_h($edit['summary']??''); ?></textarea></div><div class="nl-field"><label>상세 설명</label><textarea name="detail"><?php echo nl_h($edit['detail']??''); ?></textarea></div><div class="nl-field"><label>출처명</label><input name="source_title" value="<?php echo nl_h($edit['source_title']??''); ?>"></div><div class="nl-field"><label>출처 URL</label><input name="source_url" type="text" value="<?php echo nl_h($edit['source_url']??''); ?>" placeholder="https://..."></div><button class="nl-btn nl-btn--primary" type="submit">저장</button></form><section class="nl-panel"><h2>등록 목록</h2><ul class="nl-list"><?php foreach($rows as $r){ ?><li><div class="nl-profile-line"><strong><?php echo nl_h($r['term']); ?></strong><span><?php echo nl_h($r['category']); ?></span><?php if(!$r['is_active'])echo '<span class="nl-badge nl-badge--suspended">숨김</span>';?></div><div class="nl-actions nl-actions--compact"><a class="nl-btn nl-btn--small" href="<?php echo nl_url('glossary-manage.php?edit='.(int)$r['id']); ?>">수정</a><form method="post"><?php echo nl_csrf_field(); ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><input type="hidden" name="active" value="<?php echo $r['is_active']?0:1; ?>"><button class="nl-btn nl-btn--small" type="submit"><?php echo $r['is_active']?'숨김':'복원'; ?></button></form></div></li><?php } ?></ul></section></div></div>
<?php include_once G5_PATH.'/tail.php'; ?>
